import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if p_val < 0.05:
                sig_features.append((fid, abs(t_stat)))

    # Sort by effect size
    sig_features.sort(key=lambda x: x[1], reverse=True)

    # Check for product terms among top features
    top_features = [fid for fid, _ in sig_features[:10]]
    candidates = []

    # Look for correlated pairs with strong individual effects
    correlations = {}
    for i, fid1 in enumerate(top_features):
        for j, fid2 in enumerate(top_features[i+1:], i+1):
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0,1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr

    # Try product terms
    best_score = -np.inf
    best_product = None
    best_drivers = ()

    # Test combinations of 1-2 features
    for n_drivers in range(1, min(3, len(sig_features)+1)):
        for i in range(len(sig_features)-n_drivers+1):
            drivers = tuple(sig_features[j][0] for j in range(i, i+n_drivers))

            # Try all possible product terms
            for fid1, fid2 in correlations:
                if fid1 in drivers or fid2 in drivers:
                    continue

                # Check if this product improves prediction
                cols = [feats.column(f) for f in drivers]
                X = feats.x[:, cols].copy()

                # Add product term
                prod_col = feats.column(fid1) + feats.column(fid2) + 1000  # Unique column
                X = np.column_stack([X, feats.x[:, feats.column(fid1)] * feats.x[:, feats.column(fid2)]])

                # Simple CV-like check
                try:
                    model = LogisticRegression(penalty='l1', solver='liblinear', C=0.1)
                    model.fit(X, feats.y)
                    score = model.score(X, feats.y)
                    if score > best_score:
                        best_score = score
                        best_drivers = drivers
                        best_product = (fid1, fid2)
                except:
                    pass

    # If we found a good product term, return it
    if best_product and len(best_drivers) <= MAX_DRIVERS:
        return Design(
            drivers=best_drivers,
            columns=list(best_drivers) + [best_product[0], best_product[1]],
            products=[best_product],
            loadings={}
        )

    # Otherwise return simple linear model
    if sig_features:
        drivers = tuple(fid for fid, _ in sig_features[:MAX_DRIVERS])
        return Design(
            drivers=drivers,
            columns=list(drivers),
            products=[],
            loadings={}
        )

    return Design(drivers=(), columns=[], products=[], loadings={})

